import * as T from 'three';
import {OrbitControls} from '/vendor/OrbitControls.js';
import {initTheme,resolveColor,applyToThree} from '/theme-engine.js';
const $=id=>document.getElementById(id),host=$('viewport'),scene=new T.Scene();scene.background=new T.Color('#e5e9db');
const renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;host.append(renderer.domElement);
const camera=new T.PerspectiveCamera(35,1,.01,1000),controls=new OrbitControls(camera,renderer.domElement);controls.enablePan=false;controls.maxPolarAngle=Math.PI*.49;
scene.add(new T.HemisphereLight('#fff7e8','#8a9e7a',2));const sun=new T.DirectionalLight('#fff1d5',2.5);sun.position.set(-7,12,9);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-12,right:12,top:12,bottom:-12,far:60});sun.shadow.normalBias=.03;scene.add(sun);
const floor=new T.Mesh(new T.CylinderGeometry(1,1,.06,64),new T.MeshStandardMaterial({color:'#cfd9bb',roughness:1}));floor.position.y=-.045;floor.receiveShadow=true;scene.add(floor);
let records=[],category='all',selected=null,current=null,serial=0;const cache=new Map(),thumbs=new Map();
const title=s=>s.replace(/[-_]/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
function render(){renderer.render(scene,camera)}controls.addEventListener('change',()=>{render();window.RanchView?.changed()});
function fit(){if(!current)return;const bounds=new T.Box3().setFromObject(current),center=bounds.getCenter(new T.Vector3()),size=bounds.getSize(new T.Vector3()),radius=size.length()/2;const fitAngle=Math.min(camera.fov*Math.PI/360,Math.atan(Math.tan(camera.fov*Math.PI/360)*camera.aspect));camera.position.copy(center).add(new T.Vector3(1,.65,1.3).normalize().multiplyScalar(radius/Math.sin(fitAngle)*1.25));controls.target.copy(center);controls.minDistance=radius*.6;controls.maxDistance=radius*12;controls.update();render()}
new ResizeObserver(()=>{renderer.setSize(host.clientWidth,host.clientHeight,false);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();fit();render()}).observe(host);
async function model(record){if(!cache.has(record.id))cache.set(record.id,(async()=>{const response=await fetch(record.json);if(!response.ok)throw Error('Asset is not available yet');const parts=await response.json(),group=new T.Group();for(const part of parts){const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(part.positions,3));if(part.normals?.length===part.positions.length)g.setAttribute('normal',new T.Float32BufferAttribute(part.normals,3));else g.computeVertexNormals();const color=new T.Color().setRGB(...resolveColor(part),T.SRGBColorSpace),mesh=new T.Mesh(g,new T.MeshStandardMaterial({color,roughness:.9}));mesh.userData.themeSurface=part;mesh.castShadow=mesh.receiveShadow=true;group.add(mesh)}return group})());const group=(await cache.get(record.id)).clone(true);applyToThree(group,T);return group}
async function show(record){const ticket=++serial;selected=record;$('status').textContent='Opening '+title(record.subject)+'…';try{const group=await model(record);if(ticket!==serial)return;if(current)scene.remove(current);current=group;scene.add(group);const box=new T.Box3().setFromObject(group),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3());floor.scale.setScalar(Math.max(size.x,size.z)*.7);floor.position.set(center.x,box.min.y-.045,center.z);$('asset-title').textContent=title(record.subject);$('description').textContent='Soft toy · '+title(record.state)+' · Drag to turn';$('download').hidden=false;$('download').href=record.glb;$('status').textContent=(record.triangles||0).toLocaleString()+' triangles · static state model';$('mapping').textContent='Simulation mapping: '+JSON.stringify(record.simulationMapping||'Visual study');$('states').replaceChildren();for(const r of records.filter(r=>r.subject===record.subject&&r.category===record.category)){const b=document.createElement('button');b.textContent=title(r.state);b.setAttribute('aria-pressed',String(r.id===record.id));b.onclick=()=>show(r);$('states').append(b)}document.querySelectorAll('.model').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.subject===record.subject)));history.replaceState(null,'','?asset='+encodeURIComponent(record.id));fit();window.RanchView?.changed()}catch(e){$('status').textContent=e.message;console.error(e)}}
let thumbRenderer;async function thumbnail(record){if(thumbs.has(record.id))return thumbs.get(record.id);const group=await model(record);if(!thumbRenderer){thumbRenderer=new T.WebGLRenderer({antialias:true});thumbRenderer.setSize(160,130);thumbRenderer.setClearColor('#e5e9db')}const s=new T.Scene();s.add(group,new T.HemisphereLight('#fff7e8','#8a9e7a',2));const l=new T.DirectionalLight('#fff1d5',2.5);l.position.set(-7,12,9);s.add(l);const b=new T.Box3().setFromObject(group),c=b.getCenter(new T.Vector3()),r=b.getSize(new T.Vector3()).length()/2,cam=new T.PerspectiveCamera(35,160/130,.01,1000);cam.position.copy(c).add(new T.Vector3(1,.65,1.3).normalize().multiplyScalar(r/Math.sin(35*Math.PI/360)*1.15));cam.lookAt(c);thumbRenderer.render(s,cam);const url=thumbRenderer.domElement.toDataURL();thumbs.set(record.id,url);return url}
function shelf(){const subjects=new Map();for(const r of records.filter(r=>category==='all'||r.category===category)){const k=r.category+':'+r.subject;if(!subjects.has(k)||['complete','idle','full','standing','mature'].includes(r.state))subjects.set(k,r)}$('models').replaceChildren();for(const r of subjects.values()){const b=document.createElement('button');b.className='model';b.dataset.subject=r.subject;b.setAttribute('aria-pressed',String(selected?.subject===r.subject));const img=document.createElement('img');img.alt='';const span=document.createElement('span'),strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=title(r.subject);small.textContent=records.filter(a=>a.subject===r.subject&&a.category===r.category).length+' states';span.append(strong,small);b.append(img,span);b.onclick=()=>{show(r);if(innerWidth<800)document.querySelector('.stage').scrollIntoView({behavior:'smooth',block:'start'})};$('models').append(b);thumbnail(r).then(url=>img.src=url).catch(()=>img.remove())}}
async function refresh(){const response=await fetch('/simulation-assets/catalog.json?t='+Date.now());if(!response.ok)throw Error('Library is being published');records=await response.json();$('count').textContent=records.length+' models';shelf();if(!selected&&records.length){const requested=new URLSearchParams(location.search).get('asset');await show(records.find(r=>r.id===requested)||records.find(r=>r.state==='complete')||records[0])}}
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));shelf()});$('fit').onclick=fit;$('turn').onclick=()=>{const v=camera.position.clone().sub(controls.target).applyAxisAngle(new T.Vector3(0,1,0),Math.PI/6);camera.position.copy(controls.target).add(v);controls.update();render()};$('refresh').onclick=()=>refresh().catch(e=>$('status').textContent=e.message);
window.RanchView?.register('simulationAssets',()=>({selected:selected?.id,category,count:records.length,camera:camera.position.toArray()}),render);
window.addEventListener('ranch-theme-change',()=>{if(current)applyToThree(current,T);thumbs.clear();shelf();render()});
initTheme().then(refresh).catch(e=>$('status').textContent=e.message);
